// A UUIDv7 minted in the browser (ARCHITECTURE invariant 2: ids are UUIDv7, generated by the
// device that observed the event): 48 bits of milliseconds, version 7, variant 10, the rest
// random. The office originates two kinds of record under ids of its own, kept across
// retries so the server can answer a resend as a duplicate: a closeout, and the events of a
// labor repair. Consumed by closeout-screen.tsx and ledger/repair-set.ts.
export function uuidv7(ms: number = Date.now()): string {
  if (!Number.isInteger(ms) || ms < 0 || ms > 0xffff_ffff_ffff) {
    throw new Error("uuidv7: ms out of range");
  }
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let rest = ms;
  for (let i = 5; i >= 0; i--) {
    bytes[i] = rest % 256;
    rest = Math.floor(rest / 256);
  }
  bytes[6] = (bytes[6]! & 0x0f) | 0x70;
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
